COMMENT ON COLUMN BAT_EXECUTION_CONTROL.operator_id IS '실행 요청 운영자';
COMMENT ON COLUMN BAT_EXECUTION_CONTROL.reason IS '승인된 실행 사유';
COMMENT ON COLUMN BAT_EXECUTION_CONTROL.idempotency_key IS 'Scope 내부 실행 멱등 Key';
COMMENT ON COLUMN BAT_EXECUTION_CONTROL.fencing_token IS 'Control Plane Fencing Token';
COMMENT ON COLUMN BAT_EXECUTION_CONTROL.job_instance_id IS 'Spring Batch JobInstance ID';
COMMENT ON COLUMN BAT_EXECUTION_CONTROL.job_execution_id IS 'Spring Batch JobExecution ID';
