CREATE TABLE BAT_OPERATION_REQUEST (
    idempotency_key VARCHAR2(120 CHAR) NOT NULL,
    request_hash CHAR(64 CHAR) NOT NULL,
    operation_type VARCHAR2(80 CHAR) NOT NULL,
    target_type VARCHAR2(80 CHAR) NOT NULL,
    target_id VARCHAR2(200 CHAR) NOT NULL,
    action_type VARCHAR2(100 CHAR) NOT NULL,
    approval_request_id VARCHAR2(120 CHAR) NOT NULL,
    requested_by VARCHAR2(50 CHAR) NOT NULL,
    expected_version NUMBER(19),
    request_state VARCHAR2(30 CHAR) NOT NULL DEFAULT 'RESERVED',
    result_payload CLOB,
    failure_code VARCHAR2(80 CHAR),
    failure_message VARCHAR2(1000 CHAR),
    completed_at TIMESTAMP(3),
    created_by VARCHAR2(50 CHAR) NOT NULL DEFAULT 'BAT',
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_by VARCHAR2(50 CHAR) NOT NULL DEFAULT 'BAT',
    updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_BAT_OPERATION_REQUEST PRIMARY KEY (idempotency_key),
    CONSTRAINT ck_bat_operation_request_state CHECK (request_state IN ('RESERVED','COMPLETED','FAILED','UNKNOWN')),
    CONSTRAINT ck_bat_operation_request_hash CHECK (CHAR_LENGTH(request_hash) = 64)
);
CREATE INDEX ix_bat_operation_request_target ON BAT_OPERATION_REQUEST (target_type, target_id, created_at);
CREATE INDEX ix_bat_operation_request_state ON BAT_OPERATION_REQUEST (request_state, updated_at);
COMMENT ON TABLE BAT_OPERATION_REQUEST IS 'BAT 위험조치 승인·멱등·UNKNOWN 복구 Ledger';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.idempotency_key IS 'BAT 위험조치 멱등 키';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.request_hash IS 'Canonical 위험조치 SHA-256';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.operation_type IS 'BAT Owner operation';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.target_type IS '위험조치 대상 유형';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.target_id IS '위험조치 대상 ID';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.action_type IS '감사 Action 유형';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.approval_request_id IS 'ADM 승인 요청 식별자';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.requested_by IS '검증된 실행 운영자';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.expected_version IS '대상 낙관적 잠금 Version';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.request_state IS 'RESERVED/COMPLETED/FAILED/UNKNOWN';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.result_payload IS '멱등 Replay용 마스킹 결과';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.failure_code IS '실패/결과불명 코드';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.failure_message IS '마스킹된 실패/결과불명 메시지';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.completed_at IS '최종 상태 확정 일시';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.created_by IS '등록자';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.created_at IS '등록일시';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.updated_by IS '수정자';
COMMENT ON COLUMN BAT_OPERATION_REQUEST.updated_at IS '수정일시';

CREATE TABLE BAT_REMOTE_MESSAGE_LEDGER (
