CREATE TABLE CPF_TRANSACTION_LINEAGE (
    lineage_id VARCHAR2(64 CHAR) NOT NULL,
    transaction_id CHAR(34 CHAR) NOT NULL,
    segment_id VARCHAR2(128 CHAR) NOT NULL,
    parent_segment_id VARCHAR2(128 CHAR),
    attempt_no NUMBER(10) NOT NULL DEFAULT 1,
    trace_id VARCHAR2(128 CHAR),
    span_id VARCHAR2(128 CHAR),
    request_id VARCHAR2(128 CHAR),
    idempotency_key VARCHAR2(160 CHAR),
    tenant_id VARCHAR2(128 CHAR),
    system_code VARCHAR2(64 CHAR),
    target_system_code VARCHAR2(128 CHAR),
    current_channel VARCHAR2(64 CHAR),
    actor_id_masked VARCHAR2(256 CHAR),
    instance_id VARCHAR2(128 CHAR),
    was_id VARCHAR2(128 CHAR),
    agent_id VARCHAR2(128 CHAR),
    worker_id VARCHAR2(128 CHAR),
    target_channel VARCHAR2(128 CHAR),
    operation_id VARCHAR2(160 CHAR),
    message_id VARCHAR2(160 CHAR),
    consumer_group VARCHAR2(160 CHAR),
    dlq_id VARCHAR2(160 CHAR),
    batch_job_instance_id VARCHAR2(128 CHAR),
    batch_job_execution_id VARCHAR2(128 CHAR),
    batch_step_execution_id VARCHAR2(128 CHAR),
    partition_id VARCHAR2(128 CHAR),
    file_id VARCHAR2(160 CHAR),
    source_type VARCHAR2(32 CHAR) NOT NULL,
    source_ref_id VARCHAR2(256 CHAR),
    lifecycle_state VARCHAR2(32 CHAR) NOT NULL,
    failure_stage VARCHAR2(128 CHAR),
    unknown_yn CHAR(1 CHAR) NOT NULL DEFAULT 'N',
    reconcile_state VARCHAR2(32 CHAR),
    occurred_at TIMESTAMP(6) NOT NULL,
    freshness_at TIMESTAMP(6) NOT NULL,
    payload_hash CHAR(64 CHAR) NOT NULL,
    archived_at TIMESTAMP(6),
    CONSTRAINT pk_CPF_TRANSACTION_LINEAGE PRIMARY KEY (lineage_id, occurred_at),
    CONSTRAINT uk_cpf_tx_lineage_event UNIQUE (transaction_id, segment_id, attempt_no, source_type, payload_hash, occurred_at),
    CONSTRAINT ck_cpf_tx_lineage_unknown CHECK (unknown_yn IN ('Y','N'))
);
CREATE INDEX idx_cpf_tx_lineage_tx_time ON CPF_TRANSACTION_LINEAGE (transaction_id, occurred_at, segment_id, attempt_no);
