CREATE TABLE OPS_RUNTIME_LOCK (
    lock_key VARCHAR2(200 CHAR) NOT NULL,
    owner_id VARCHAR2(200 CHAR) NOT NULL,
    request_id VARCHAR2(200 CHAR) NOT NULL,
    fencing_token NUMBER(19) NOT NULL,
    owner_epoch NUMBER(19) NOT NULL,
    version_no NUMBER(19) NOT NULL,
    acquired_at TIMESTAMP(6) NOT NULL,
    lease_until TIMESTAMP(6) NOT NULL,
    lock_state VARCHAR2(32 CHAR) NOT NULL,
    last_reason VARCHAR2(1000 CHAR),
    updated_at TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_OPS_RUNTIME_LOCK PRIMARY KEY (lock_key),
    CONSTRAINT ck_cpf_runtime_lock_state CHECK (lock_state IN ('ACTIVE','RELEASED','EXPIRED','FORCE_RELEASED')),
    CONSTRAINT ck_cpf_runtime_lock_token CHECK (fencing_token >= 1 AND owner_epoch >= 1 AND version_no >= 1)
);
CREATE INDEX idx_cpf_runtime_lock_lease ON OPS_RUNTIME_LOCK (lock_state, lease_until, lock_key);
CREATE INDEX idx_cpf_runtime_lock_owner ON OPS_RUNTIME_LOCK (owner_id, request_id, lock_state);
COMMENT ON TABLE OPS_RUNTIME_LOCK IS 'CPF topology-independent lock 계약의 JDBC durable provider 상태. lease/fencing/owner epoch/stale writer 차단을 지원.';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.lock_key IS '잠금 키';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.owner_id IS '현재 owner';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.request_id IS '획득 요청 ID';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.fencing_token IS '단조 증가 fencing token';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.owner_epoch IS 'owner takeover epoch';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.version_no IS 'optimistic version';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.acquired_at IS '획득 시각';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.lease_until IS 'lease 만료 시각';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.lock_state IS 'ACTIVE/RELEASED/EXPIRED/FORCE_RELEASED';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.last_reason IS '마지막 상태 변경 사유';
COMMENT ON COLUMN OPS_RUNTIME_LOCK.updated_at IS '최종 변경 시각';

