COMMENT ON COLUMN BAT_DEPLOYMENT_EXECUTION.expected_version IS 'Expected deployment plan version';
COMMENT ON COLUMN BAT_DEPLOYMENT_EXECUTION.approval_request_id IS 'Approval request identifier';
