CREATE TABLE CMN_TEMPLATE_AUDIT (
    AUDIT_ID VARCHAR2(64 CHAR) NOT NULL,
    TEMPLATE_CODE VARCHAR2(100 CHAR) NOT NULL,
    TEMPLATE_VERSION NUMBER(19) NOT NULL,
    CHANNEL_CODE VARCHAR2(30 CHAR) NOT NULL,
    ACTION_TYPE VARCHAR2(30 CHAR) NOT NULL,
    REQUEST_USER VARCHAR2(100 CHAR) NOT NULL,
    REQUEST_REASON VARCHAR2(500 CHAR) NOT NULL,
    BEFORE_STATUS VARCHAR2(30 CHAR),
    AFTER_STATUS VARCHAR2(30 CHAR) NOT NULL,
    REVISION_NO NUMBER(19) NOT NULL,
    OCCURRED_AT TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    CONSTRAINT pk_CMN_TEMPLATE_AUDIT PRIMARY KEY (AUDIT_ID),
    CONSTRAINT CK_CMN_TEMPLATE_AUDIT_ACTION CHECK (ACTION_TYPE IN ('CREATE_DRAFT','APPROVE','SUPERSEDE','RETIRE')),
    CONSTRAINT CK_CMN_TEMPLATE_AUDIT_REVISION CHECK (REVISION_NO >= 0),
    CONSTRAINT FK_CMN_TEMPLATE_AUDIT_DEFINITION FOREIGN KEY (TEMPLATE_CODE, TEMPLATE_VERSION, CHANNEL_CODE) REFERENCES CMN_TEMPLATE_DEFINITION (TEMPLATE_CODE, TEMPLATE_VERSION, CHANNEL_CODE)
);
CREATE INDEX IX_CMN_TEMPLATE_AUDIT_LOOKUP ON CMN_TEMPLATE_AUDIT (TEMPLATE_CODE, CHANNEL_CODE, TEMPLATE_VERSION, OCCURRED_AT);
COMMENT ON TABLE CMN_TEMPLATE_AUDIT IS 'CMN Template 변경 append-only 감사 원장';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.AUDIT_ID IS '감사 이벤트 ID';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.TEMPLATE_CODE IS 'Template 식별 코드';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.TEMPLATE_VERSION IS 'Template 버전';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.CHANNEL_CODE IS '채널 코드';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.ACTION_TYPE IS 'CREATE_DRAFT/APPROVE/SUPERSEDE/RETIRE';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.REQUEST_USER IS '요청자';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.REQUEST_REASON IS '변경 사유';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.BEFORE_STATUS IS '변경 전 상태';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.AFTER_STATUS IS '변경 후 상태';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.REVISION_NO IS '변경 후 Revision';
COMMENT ON COLUMN CMN_TEMPLATE_AUDIT.OCCURRED_AT IS '발생 시각';

CREATE TABLE CPF_DATA_QUALITY_OPERATION (
    OPERATION_ID VARCHAR2(160 CHAR) NOT NULL,
    OPERATION_TYPE VARCHAR2(64 CHAR) NOT NULL,
    QUARANTINE_ID VARCHAR2(64 CHAR) NOT NULL,
