CREATE INDEX IX_CPF_DQ_OPERATION_TARGET ON CPF_DATA_QUALITY_OPERATION (QUARANTINE_ID, OPERATION_TYPE, CREATED_AT);
COMMENT ON TABLE CPF_DATA_QUALITY_OPERATION IS 'Persistent DQ replay/reconcile idempotency ledger';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.OPERATION_ID IS 'Replay/reconcile idempotency operation ID';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.OPERATION_TYPE IS 'Operation type';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.QUARANTINE_ID IS 'Target quarantine ID';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.COMMAND_FINGERPRINT IS 'SHA-256 command fingerprint';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.RESULT_PAYLOAD IS 'Durable replay result JSON';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.ACTOR_ID IS 'Actor ID';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.ACTION_REASON IS 'Action reason';
COMMENT ON COLUMN CPF_DATA_QUALITY_OPERATION.CREATED_AT IS 'Created time';

CREATE TABLE CPF_NOTIFICATION_DELIVERY_LOG (
    delivery_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    rule_id NUMBER(19),
    event_type VARCHAR2(80 CHAR) NOT NULL,
    target_type VARCHAR2(80 CHAR),
    target_id VARCHAR2(120 CHAR),
    receiver VARCHAR2(200 CHAR),
    delivery_status VARCHAR2(30 CHAR) NOT NULL DEFAULT 'READY',
    delivery_message VARCHAR2(2000 CHAR),
    requested_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    delivered_at TIMESTAMP(3),
    created_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    operation_id VARCHAR2(100 CHAR) NOT NULL,
    request_hash VARCHAR2(64 CHAR) NOT NULL,
    payload_body VARCHAR2(2000 CHAR) NOT NULL,
    attempt_count NUMBER(10) NOT NULL DEFAULT 0,
    max_attempts NUMBER(10) NOT NULL DEFAULT 3,
    next_attempt_at TIMESTAMP(3),
    lease_owner VARCHAR2(100 CHAR),
    lease_until TIMESTAMP(3),
