COMMENT ON COLUMN OPS_RUNTIME_CHANGE.expires_at IS 'Expiry time';
COMMENT ON COLUMN OPS_RUNTIME_CHANGE.reason IS 'Mandatory operation reason';
COMMENT ON COLUMN OPS_RUNTIME_CHANGE.approval_id IS 'Approval request identifier';
COMMENT ON COLUMN OPS_RUNTIME_CHANGE.break_glass_id IS 'Break-glass authorization identifier';
