    LEASE_EXPIRES_AT TIMESTAMP(3),
    FENCE_TOKEN NUMBER(19) NOT NULL DEFAULT 0,
    created_by VARCHAR2(50 CHAR) NOT NULL DEFAULT 'ADM',
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
