    CONSTRAINT ck_bat_result_timeout CHECK (timeout_yn IN ('Y','N')),
    CONSTRAINT ck_bat_result_unknown CHECK (unknown_yn IN ('Y','N')),
    CONSTRAINT ck_bat_result_truncated CHECK (output_truncated_yn IN ('Y','N')),
