CREATE TABLE OPS_RUNTIME_DELIVERY (
    delivery_id VARCHAR2(80 CHAR) NOT NULL,
    change_id VARCHAR2(80 CHAR) NOT NULL,
    instance_id VARCHAR2(120 CHAR) NOT NULL,
    sequence_no NUMBER(10) NOT NULL,
    desired_version NUMBER(19) NOT NULL,
    delivery_state VARCHAR2(30 CHAR) NOT NULL DEFAULT 'PENDING',
    attempt_no NUMBER(10) NOT NULL DEFAULT 0,
    next_attempt_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    fencing_token NUMBER(19),
    claimed_at TIMESTAMP(3),
    acknowledged_at TIMESTAMP(3),
    actual_hash VARCHAR2(64 CHAR),
    error_code VARCHAR2(80 CHAR),
    error_message VARCHAR2(900 CHAR),
    created_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_OPS_RUNTIME_DELIVERY PRIMARY KEY (delivery_id),
    CONSTRAINT ck_cpf_runtime_delivery_state CHECK (delivery_state IN ('PENDING','CLAIMED','ACKED','FAILED','POISONED','UNKNOWN_RESULT','RESTART_REQUIRED','CANCELLED','EXPIRED','SUPERSEDED')),
    CONSTRAINT fk_cpf_runtime_delivery_change FOREIGN KEY (change_id) REFERENCES OPS_RUNTIME_CHANGE (change_id) ON DELETE CASCADE,
    CONSTRAINT fk_cpf_runtime_delivery_instance FOREIGN KEY (instance_id) REFERENCES OPS_SERVICE_INSTANCE (instance_id) ON DELETE CASCADE
);
CREATE INDEX ix_cpf_runtime_delivery_claim ON OPS_RUNTIME_DELIVERY (instance_id, delivery_state, next_attempt_at, sequence_no);
CREATE INDEX ix_cpf_runtime_delivery_change ON OPS_RUNTIME_DELIVERY (change_id, delivery_state);
COMMENT ON TABLE OPS_RUNTIME_DELIVERY IS 'Runtime durable per-instance delivery inbox';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.delivery_id IS 'Runtime delivery identifier';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.change_id IS 'Runtime change identifier';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.instance_id IS 'Runtime instance identifier';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.sequence_no IS 'Delivery sequence number';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.desired_version IS 'Desired state version';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.delivery_state IS 'Runtime delivery lifecycle state';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.attempt_no IS 'Delivery attempt number';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.next_attempt_at IS 'Next delivery attempt time';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.fencing_token IS 'Monotonic fencing token';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.claimed_at IS 'Delivery claim time';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.acknowledged_at IS 'Delivery acknowledgment time';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.actual_hash IS 'Applied state checksum';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.error_code IS 'Failure code';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.error_message IS 'Masked failure message';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.created_by IS 'Creator identifier';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.created_at IS 'Creation time';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.updated_by IS 'Last updater identifier';
COMMENT ON COLUMN OPS_RUNTIME_DELIVERY.updated_at IS 'Last update time';
CREATE OR REPLACE TRIGGER trg_touch_OPS_RUNTIME_DELIVERY BEFORE UPDATE ON OPS_RUNTIME_DELIVERY FOR EACH ROW BEGIN :NEW.updated_at := CURRENT_TIMESTAMP; END;
/

